"use client";

import { useState } from "react";
import { T } from "@/lib/design-tokens";
import type { ExerciseRow } from "@/lib/exercise-library";
import MuscleMap from "./MuscleMap";

// Primary card visual = the TARGET MUSCLE GROUP. Prefers an AI-generated
// anatomical illustration of the movement (ex.illustrationUrl, generated by
// scripts/gen-exercise-illustrations.mjs) when present; otherwise falls back to
// the interactive MuscleMap that highlights the worked muscles. On a broken
// illustration URL it also falls back to the map.

type Props = {
  ex: Pick<ExerciseRow, "illustrationUrl" | "primary_muscles" | "secondary_muscles">;
  size?: number;
};

export default function ExerciseIllustration({ ex, size = 120 }: Props) {
  const [broken, setBroken] = useState(false);
  const hasIllustration = !!ex.illustrationUrl && !broken;

  if (!hasIllustration) {
    return <MuscleMap primary={ex.primary_muscles} secondary={ex.secondary_muscles} size={size} />;
  }

  return (
    <div style={{ width: size, height: size, position: "relative", borderRadius: 12, overflow: "hidden", flexShrink: 0 }}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={ex.illustrationUrl!}
        alt=""
        loading="lazy"
        onError={() => setBroken(true)}
        style={{ width: "100%", height: "100%", objectFit: "contain" }}
      />
      <div style={{ position: "absolute", inset: 0, borderRadius: 12, boxShadow: `inset 0 0 0 1px ${T.border}`, pointerEvents: "none" }} />
    </div>
  );
}
